PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS sf_accounts(id TEXT PRIMARY KEY,alias TEXT NOT NULL,recovery_hash TEXT UNIQUE NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sf_sessions(token_hash TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES sf_accounts(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sf_projects(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES sf_accounts(id) ON DELETE CASCADE,title TEXT NOT NULL,body TEXT NOT NULL,body_hash TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),write_id TEXT NOT NULL,create_request TEXT NOT NULL,create_signature TEXT NOT NULL,parent_cut TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(owner_id,create_request));
CREATE TABLE IF NOT EXISTS sf_members(project_id TEXT NOT NULL REFERENCES sf_projects(id) ON DELETE CASCADE,account_id TEXT NOT NULL REFERENCES sf_accounts(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN('owner','editor','viewer')),joined_at INTEGER NOT NULL,PRIMARY KEY(project_id,account_id));
CREATE TABLE IF NOT EXISTS sf_versions(project_id TEXT NOT NULL REFERENCES sf_projects(id) ON DELETE CASCADE,revision INTEGER NOT NULL,body TEXT NOT NULL,body_hash TEXT NOT NULL,author_id TEXT REFERENCES sf_accounts(id) ON DELETE SET NULL,write_id TEXT NOT NULL,saved_at INTEGER NOT NULL,PRIMARY KEY(project_id,revision),UNIQUE(project_id,write_id));
CREATE TABLE IF NOT EXISTS sf_invites(token_hash TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES sf_projects(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN('editor','viewer')),created_by TEXT NOT NULL REFERENCES sf_accounts(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL,used_by TEXT,revoked_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sf_cuts(id TEXT PRIMARY KEY,author_id TEXT REFERENCES sf_accounts(id) ON DELETE SET NULL,author_alias TEXT NOT NULL,title TEXT NOT NULL,summary TEXT NOT NULL,body TEXT NOT NULL,body_hash TEXT NOT NULL,creative_hash TEXT NOT NULL,parent_cut TEXT REFERENCES sf_cuts(id),project_id TEXT,source_revision INTEGER NOT NULL,request_id TEXT NOT NULL,request_signature TEXT NOT NULL,license TEXT NOT NULL CHECK(license='CC-BY-4.0'),changes TEXT NOT NULL,withdrawn_at INTEGER,hidden_at INTEGER,created_at INTEGER NOT NULL,UNIQUE(project_id,source_revision),UNIQUE(author_id,request_id));
CREATE TABLE IF NOT EXISTS sf_reports(id TEXT PRIMARY KEY,cut_id TEXT NOT NULL REFERENCES sf_cuts(id) ON DELETE CASCADE,reporter_hash TEXT NOT NULL,reason TEXT NOT NULL CHECK(reason IN('spam','unsafe','rights','privacy')),note TEXT NOT NULL,created_at INTEGER NOT NULL,resolved_at INTEGER,UNIQUE(cut_id,reporter_hash));
CREATE TABLE IF NOT EXISTS sf_rate_limits(rate_key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sf_subscriptions(subscription_id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES sf_accounts(id) ON DELETE CASCADE,customer_id TEXT NOT NULL,status TEXT NOT NULL,is_live INTEGER NOT NULL,expires_at INTEGER NOT NULL,last_event_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sf_checkout_intents(account_id TEXT PRIMARY KEY REFERENCES sf_accounts(id) ON DELETE CASCADE,intent_id TEXT UNIQUE NOT NULL,request_id TEXT NOT NULL,price_id TEXT NOT NULL,provider_session_id TEXT,url TEXT,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sf_checkout_sessions(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES sf_accounts(id) ON DELETE CASCADE,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sf_billing_events(id TEXT PRIMARY KEY,payload_hash TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sf_public_cuts ON sf_cuts(created_at DESC) WHERE withdrawn_at IS NULL AND hidden_at IS NULL;
CREATE INDEX IF NOT EXISTS sf_members_account ON sf_members(account_id);
CREATE INDEX IF NOT EXISTS sf_sessions_expiry ON sf_sessions(expires_at);
